import io.netty.bootstrap.ServerBootstrap;
import io.netty.channel.ChannelFuture;
import io.netty.channel.ChannelInitializer;
import io.netty.channel.ChannelOption;
import io.netty.channel.ChannelPipeline;
import io.netty.channel.EventLoopGroup;
import io.netty.channel.ServerChannel;
import io.netty.channel.SimpleChannelInboundHandler;
import io.netty.channel.nio.NioEventLoopGroup;
import io.netty.channel.socket.nio.NioServerSocketChannel;

public class NetworkSniffer {
    public static void main(String[] args) throws Exception {
        // Configurações da rede
        int port = 4000;
        int bufferSize = 1024;
        EventLoopGroup group = new NioEventLoopGroup();
        ServerBootstrap bootstrap = new ServerBootstrap();
        bootstrap.group(group)
                .channel(NioServerSocketChannel.class)
                .option(ChannelOption.SO_BACKLOG, 100)
                .option(ChannelOption.SO_KEEPALIVE, true)
                .option(ChannelOption.SO_SNDBUF, bufferSize)
                .option(ChannelOption.SO_RCVBUF, bufferSize)
                .channelInboundHandler(new ChannelInitializer<SocketChannel>() {
                    @Override
                    public void initChannel(SocketChannel ch) throws Exception {
                        ChannelPipeline p = ch.pipeline();
                        p.addLast(new NetworkSnifferHandler());
                    }
                });
        // Cria o servidor
        ChannelFuture future = bootstrap.bind(port).sync();
        System.out.println("Sniffer de rede iniciado na porta " + port);
        // Aguarda o servidor ser fechado
        future.channel().closeFuture().sync();
    }
}

